'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

import { CommentField } from './_parts/comment-field';
import { draftCommentOf } from './_parts/comment-model';
import { CommentMeta, CommentText, PersonAvatar } from './_parts/comment-parts';
import { ENTER, heightPresenceOf } from './_parts/motion-parts';
import { personOf } from './_parts/people';
import { NOW } from './_parts/time';

type Entry = {
  id: string;
  authorId: string;
  at: string;
  /** Empty while the author is still typing. */
  body: string | null;
};

type Reply = {
  authorId: string;
  body: string;
};

const FIRST_TYPING_MS = 3200;

const TYPING_STARTS_AFTER_MS = 900;

const TYPING_LASTS_MS = 2600;

const DOT_DELAYS = [0, 0.15, 0.3];

const FIRST_ENTRIES: Entry[] = [
  {
    id: 'w1',
    authorId: 'leo',
    at: '2026-11-05T10:31:00',
    body: 'Totals row is done. Anyone against bold for that last line?',
  },
  {
    id: 'w2',
    authorId: 'sana',
    at: NOW,
    body: null,
  },
];

const FIRST_REPLY = 'Bold is fine, finance prints it anyway.';

const LATER_REPLIES: Reply[] = [
  {
    authorId: 'tomas',
    body: 'Thanks, I will check it on the October file after lunch.',
  },
  {
    authorId: 'leo',
    body: 'Noted. I will fold that into the totals row change.',
  },
];

function TypingDots() {
  const shouldReduceMotion = usePrefersReducedMotion();
  if (shouldReduceMotion) {
    return (
      <span aria-hidden='true' className='flex gap-1'>
        {DOT_DELAYS.map((delay) => (
          <span
            key={delay}
            className='bg-muted-foreground/60 size-1.5 rounded-full'
          />
        ))}
      </span>
    );
  }
  return (
    <span aria-hidden='true' className='flex gap-1'>
      {DOT_DELAYS.map((delay) => (
        <motion.span
          key={delay}
          animate={{ opacity: [0.25, 1, 0.25] }}
          transition={{
            duration: 1.2,
            delay,
            repeat: Infinity,
            ease: 'linear',
          }}
          className='bg-muted-foreground size-1.5 rounded-full'
        />
      ))}
    </span>
  );
}

function contentKeyOf(entry: Entry) {
  if (entry.body === null) {
    return `${entry.id}-typing`;
  }
  return `${entry.id}-comment`;
}

/** One row that holds the typing state, then becomes the comment once it is sent. */
function EntryRow({ entry }: { entry: Entry }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const person = personOf(entry.authorId);
  const isTyping = entry.body === null;

  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <div className='flex gap-3 py-2'>
        <PersonAvatar person={person} />
        <AnimatedSize className='min-w-0 flex-1'>
          <motion.div
            key={contentKeyOf(entry)}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={ENTER}
          >
            {isTyping && (
              <p className='text-muted-foreground flex min-h-7 items-center gap-2 text-xs'>
                <TypingDots />
                {person.firstName} is typing
              </p>
            )}
            {entry.body !== null && (
              <>
                <div className='flex min-h-7 items-center'>
                  <CommentMeta comment={{ ...entry, body: entry.body }} />
                </div>
                <CommentText body={entry.body} />
              </>
            )}
          </motion.div>
        </AnimatedSize>
      </div>
    </motion.li>
  );
}

function withBody(entries: Entry[], entryId: string, body: string) {
  return entries.map((entry) => {
    if (entry.id !== entryId) {
      return entry;
    }
    return { ...entry, body };
  });
}

export default function Comment08() {
  const [entries, setEntries] = useState(FIRST_ENTRIES);
  const [repliesUsed, setRepliesUsed] = useState(0);
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());

  function later(run: () => void, delay: number) {
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      run();
    }, delay);
    timers.current.add(timer);
  }

  useEffect(() => {
    const pending = timers.current;
    const timer = setTimeout(() => {
      pending.delete(timer);
      setEntries((current) => withBody(current, 'w2', FIRST_REPLY));
    }, FIRST_TYPING_MS);
    pending.add(timer);
    return () => {
      pending.forEach((item) => clearTimeout(item));
      pending.clear();
    };
  }, []);

  function answer(reply: Reply, replyIndex: number) {
    const typingId = `reply-${replyIndex}`;
    const typing: Entry = {
      id: typingId,
      authorId: reply.authorId,
      at: NOW,
      body: null,
    };
    later(() => {
      setEntries((current) => [...current, typing]);
      later(() => {
        setEntries((current) => withBody(current, typingId, reply.body));
      }, TYPING_LASTS_MS);
    }, TYPING_STARTS_AFTER_MS);
  }

  function post(body: string) {
    const comment = draftCommentOf(body);
    setEntries((current) => [...current, comment]);
    const reply = LATER_REPLIES[repliesUsed];
    if (!reply) {
      return;
    }
    setRepliesUsed((current) => current + 1);
    answer(reply, repliesUsed);
  }

  return (
    <section aria-label='Comments' className='w-full max-w-md'>
      <h3 className='text-sm font-medium'>Comments</h3>
      <ul aria-live='polite' className='mt-1'>
        <AnimatePresence initial={false}>
          {entries.map((entry) => (
            <EntryRow key={entry.id} entry={entry} />
          ))}
        </AnimatePresence>
      </ul>
      <CommentField
        placeholder='Write a comment'
        onSubmit={post}
        className='mt-2'
      />
    </section>
  );
}

'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { PersonAvatar } from './comment-parts';
import { currentUser } from './people';

type CommentFieldProps = {
  placeholder: string;
  submitLabel?: string;
  onSubmit: (body: string) => void;
  onCancel?: () => void;
  autoFocus?: boolean;
  showsAvatar?: boolean;
  className?: string;
};

function isSendKey(event: React.KeyboardEvent<HTMLTextAreaElement>) {
  const isCommand = event.metaKey || event.ctrlKey;
  return isCommand && event.key === 'Enter';
}

/** A comment field that grows with its text; Cmd or Ctrl and Enter sends, Escape leaves. */
export function CommentField({
  placeholder,
  submitLabel = 'Comment',
  onSubmit,
  onCancel,
  autoFocus = false,
  showsAvatar = true,
  className,
}: CommentFieldProps) {
  const [body, setBody] = useState('');
  const me = currentUser();
  const trimmed = body.trim();
  const canSend = trimmed.length > 0;

  function submit() {
    if (!canSend) {
      return;
    }
    onSubmit(trimmed);
    setBody('');
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    submit();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (isSendKey(event)) {
      event.preventDefault();
      submit();
      return;
    }
    if (event.key !== 'Escape') {
      return;
    }
    event.stopPropagation();
    if (onCancel) {
      onCancel();
      return;
    }
    event.currentTarget.blur();
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={cn('flex items-start gap-3', className)}
    >
      {showsAvatar && <PersonAvatar person={me} className='mt-1' />}
      <div className='relative min-w-0 flex-1'>
        <Textarea
          autoFocus={autoFocus}
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
          aria-label={placeholder}
          placeholder={placeholder}
          className='min-h-9 py-2 pe-24'
        />
        <Button
          type='submit'
          size='sm'
          disabled={!canSend}
          className='absolute end-1 bottom-1'
        >
          {submitLabel}
        </Button>
      </div>
    </form>
  );
}

import { CURRENT_USER_ID, PEOPLE } from './people';
import { NOW } from './time';

export type CommentItem = {
  id: string;
  authorId: string;
  at: string;
  body: string;
  editedAt?: string;
};

export type Segment = {
  text: string;
  isMention: boolean;
};

export const MENTION_TRIGGER = '@';

export const MENTION_NAMES = PEOPLE.map((person) => person.name);

function mentionTokensOf(names: string[]) {
  const tokens = names.map((name) => `${MENTION_TRIGGER}${name}`);
  return tokens.sort((first, second) => second.length - first.length);
}

function pushPlain(segments: Segment[], text: string) {
  if (text.length === 0) {
    return;
  }
  segments.push({ text, isMention: false });
}

/** Splits a comment into plain text and mentions of known people, written "@First Last". */
export function segmentsOf(text: string, names: string[] = MENTION_NAMES) {
  const tokens = mentionTokensOf(names);
  const segments: Segment[] = [];
  let plain = '';
  let index = 0;
  while (index < text.length) {
    const token = tokens.find((candidate) => text.startsWith(candidate, index));
    if (token) {
      pushPlain(segments, plain);
      segments.push({ text: token, isMention: true });
      plain = '';
      index += token.length;
      continue;
    }
    plain += text[index];
    index += 1;
  }
  pushPlain(segments, plain);
  return segments;
}

let draftCount = 0;

/** A comment the signed-in person just wrote, stamped with the previews' fixed now. */
export function draftCommentOf(body: string): CommentItem {
  draftCount += 1;
  return {
    id: `draft-${draftCount}`,
    authorId: CURRENT_USER_ID,
    at: NOW,
    body,
  };
}

export function commentWordOf(count: number) {
  if (count === 1) {
    return 'comment';
  }
  return 'comments';
}

export function replyWordOf(count: number) {
  if (count === 1) {
    return 'reply';
  }
  return 'replies';
}

import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import { segmentsOf, type CommentItem } from './comment-model';
import { actorNameOf, personOf, type Person } from './people';
import { relativeTimeOf } from './time';

export const MENTION_CHIP =
  'rounded-[4px] bg-primary/10 px-0.5 font-medium text-primary-ink dark:bg-primary/20';

export const TEXT_ACTION =
  'text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 inline-flex h-6 cursor-pointer items-center gap-1 rounded-md text-xs font-medium transition-colors outline-none focus-visible:ring-[3px]';

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-7 text-[10px]', className)}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

/** A comment's words, with each mention of a known person drawn as a tinted chip. */
export function CommentText({
  body,
  className,
}: {
  body: string;
  className?: string;
}) {
  const segments = segmentsOf(body);
  return (
    <p
      className={cn(
        'text-[13px] leading-5 [overflow-wrap:anywhere] whitespace-pre-wrap',
        className
      )}
    >
      {segments.map((segment, index) => {
        const key = `${index}-${segment.text}`;
        if (segment.isMention) {
          return (
            <span key={key} className={MENTION_CHIP}>
              {segment.text}
            </span>
          );
        }
        return <span key={key}>{segment.text}</span>;
      })}
    </p>
  );
}

export function CommentMeta({
  comment,
  children,
}: {
  comment: CommentItem;
  children?: React.ReactNode;
}) {
  return (
    <p className='flex min-w-0 items-baseline gap-1.5 text-[13px]'>
      <span className='truncate font-medium'>
        {actorNameOf(comment.authorId)}
      </span>
      <span aria-hidden='true' className='text-muted-foreground'>
        ·
      </span>
      <time
        dateTime={comment.at}
        className='text-muted-foreground shrink-0 text-xs tabular-nums'
      >
        {relativeTimeOf(comment.at)}
      </time>
      {children}
    </p>
  );
}

type CommentBlockProps = {
  comment: CommentItem;
  avatarClassName?: string;
  meta?: React.ReactNode;
  actions?: React.ReactNode;
  children?: React.ReactNode;
  className?: string;
};

/** Avatar, author and time, then the words aligned under the name. */
export function CommentBlock({
  comment,
  avatarClassName,
  meta,
  actions,
  children,
  className,
}: CommentBlockProps) {
  return (
    <div className={cn('flex gap-3', className)}>
      <PersonAvatar
        person={personOf(comment.authorId)}
        className={avatarClassName}
      />
      <div className='min-w-0 flex-1'>
        <div className='flex min-h-7 items-center justify-between gap-2'>
          <CommentMeta comment={comment}>{meta}</CommentMeta>
          {actions}
        </div>
        {children}
        {!children && <CommentText body={comment.body} />}
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

